#!/usr/bin/env python3
import sys
import json
import struct
import zlib
import datetime

# ISO 4217 minor units: 0, 3, or 4 decimals (default is 2)
DECIMALS_0 = {
    "BIF", "BYR", "CLP", "DJF", "GNF", "ISK", "JPY", "KMF",
    "KRW", "PYG", "RWF", "UGX", "UYI", "VND", "VUV", "XAF",
    "XOF", "XPF",
}

DECIMALS_3 = {
    "BHD", "IQD", "JOD", "KWD", "LYD", "OMR", "TND",
}

DECIMALS_4 = {
    "CLF", "UYW",
}

def get_decimals(currency: str) -> int:
    if currency in DECIMALS_0:
        return 0
    if currency in DECIMALS_3:
        return 3
    if currency in DECIMALS_4:
        return 4
    return 2

def format_amount(raw_amt: int, is_negative: bool, currency: str) -> str:
    decimals = get_decimals(currency)
    s = str(raw_amt)
    if decimals == 0:
        formatted = s
    else:
        if len(s) <= decimals:
            s = s.zfill(decimals + 1)
        formatted = s[:-decimals] + "." + s[-decimals:]
    if is_negative:
        formatted = "-" + formatted
    return formatted

def decode_varint(data: bytes, offset: int) -> tuple[int, int]:
    val = 0
    shift = 0
    data_len = len(data)
    while True:
        if offset >= data_len:
            raise ValueError("Truncated varint")
        b = data[offset]
        offset += 1
        val |= (b & 0x7F) << shift
        if not (b & 0x80):
            break
        shift += 7
    return val, offset

def decode_journal(data: bytes) -> dict:
    # Minimum valid file size:
    # 4 (magic) + 2 (num_records) + 4 (base_ts) + 3 (curr) + 1 (num_accts) + 4 (crc) = 18 bytes
    if len(data) < 18:
        raise ValueError("File too short")

    if data[:4] != b"JRN\x01":
        raise ValueError("Invalid magic number")

    stored_crc = struct.unpack("<I", data[-4:])[0]
    calc_crc = zlib.crc32(data[4:-4])
    if stored_crc != calc_crc:
        raise ValueError("CRC32 integrity check failed")

    num_records = int.from_bytes(data[4:6], "big")
    base_ts = int.from_bytes(data[6:10], "big")
    default_currency = data[10:13].decode("ascii")

    offset = 13
    num_accounts = data[offset]
    offset += 1

    accounts = []
    for _ in range(num_accounts):
        acct_len, offset = decode_varint(data, offset)
        if offset + acct_len > len(data) - 4:
            raise ValueError("Account name exceeds payload bounds")
        acct_name = data[offset:offset+acct_len].decode("utf-8")
        offset += acct_len
        accounts.append(acct_name)

    records = []
    current_ts = base_ts
    for i in range(num_records):
        if offset >= len(data) - 4:
            raise ValueError("Unexpected end of data in records")
        flag = data[offset]
        offset += 1

        has_memo = bool(flag & 0x01)
        is_negative = bool(flag & 0x02)
        has_currency = bool(flag & 0x04)
        is_pending = bool(flag & 0x08)

        status = "pending" if is_pending else "posted"

        delta_ts, offset = decode_varint(data, offset)
        current_ts += delta_ts

        if offset >= len(data) - 4:
            raise ValueError("Unexpected end of data for account index")
        acct_idx = data[offset]
        offset += 1
        if acct_idx >= len(accounts):
            raise ValueError(f"Account index out of bounds: {acct_idx}")
        account = accounts[acct_idx]

        raw_amt, offset = decode_varint(data, offset)

        if has_currency:
            if offset + 3 > len(data) - 4:
                raise ValueError("Unexpected end of data for currency code")
            currency = data[offset:offset+3].decode("ascii")
            offset += 3
        else:
            currency = default_currency

        if has_memo:
            memo_len, offset = decode_varint(data, offset)
            if offset + memo_len > len(data) - 4:
                raise ValueError("Unexpected end of data for memo")
            raw_memo = data[offset:offset+memo_len]
            offset += memo_len
            memo = bytes([b ^ 0x5a for b in raw_memo]).decode("utf-8")
        else:
            memo = None

        iso_ts = datetime.datetime.fromtimestamp(current_ts, tz=datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
        amount_str = format_amount(raw_amt, is_negative, currency)

        records.append({
            "index": i,
            "timestamp": iso_ts,
            "account": account,
            "amount": amount_str,
            "currency": currency,
            "memo": memo,
            "status": status,
        })

    if offset != len(data) - 4:
        raise ValueError(f"Payload size mismatch: {offset} != {len(data) - 4}")

    return {
        "default_currency": default_currency,
        "accounts": accounts,
        "records": records,
    }

def main():
    if len(sys.argv) < 2:
        sys.stderr.write("Usage: python jrndecode.py FILE.jrn\n")
        sys.exit(2)

    filepath = sys.argv[1]
    try:
        with open(filepath, "rb") as f:
            data = f.read()
    except Exception as e:
        sys.stderr.write(f"Error opening file: {e}\n")
        sys.exit(2)

    try:
        journal = decode_journal(data)
    except Exception as e:
        sys.stderr.write(f"Decoding error: {e}\n")
        sys.exit(2)

    print(json.dumps(journal, indent=2, ensure_ascii=False))
    sys.exit(0)

if __name__ == "__main__":
    main()
EOF
